import pandas as pd, numpy as np
m=pd.read_csv('data/movies2.csv'); p=pd.read_csv('data/people2.csv')
m=m.set_index('movie_id')

def analyze(role, variant):
    q=p[p.role==role].copy()
    if variant=='dropna':
        q=q[q.gender.notna()]
        keep=set(q.movie_id)
    elif variant=='nan_male':
        q['gender']=q.gender.fillna('m'); keep=set(q.movie_id)
    elif variant=='exclude_any_untagged':
        bad=set(p[(p.role==role)&p.gender.isna()].movie_id)
        q=q[q.gender.notna()]; keep=set(q.movie_id)-bad
    elif variant=='exclude_any_untagged_global':
        bad=set(p[p.gender.isna()].movie_id)
        q=q[q.gender.notna()]; keep=set(q.movie_id)-bad
    g=q.groupby(['movie_id','gender']).size().unstack(fill_value=0)
    g['n']=g.sum(axis=1); g['f']=g.get('f',0)
    mm=m.loc[list(keep & set(g.index))].join(g[['f','n']],how='left')
    f=mm.f; n=mm.n
    masks={'all_men':f==0,'ge1':f>=1,'2plus':f>=2,'all_women':(f==n)&(f>0)}
    out={k:(len(mm[x]), round((mm[x].rating<3).mean()*100,1)) for k,x in masks.items()}
    return out

for role in ['w','p','d']:
    print('===',role)
    for v in ['dropna','nan_male','exclude_any_untagged','exclude_any_untagged_global']:
        print(v, analyze(role,v))
