import pandas as pd, numpy as np
m=pd.read_csv('data/movies2.csv'); p=pd.read_csv('data/people2.csv')
def comp(role, ids):
    q=p[(p.role==role)&(p.movie_id.isin(ids))].assign(gender=p.gender.fillna('u'))
    d=q.pivot_table(index='movie_id',columns='gender',values='person_name',aggfunc='count',fill_value=0); d.columns.name=None
    for c in 'fmu': d[c]=d.get(c,0)
    d=d.join(m.set_index('movie_id').rating)
    out=pd.concat([d[(d.f==0)&(d.u==0)].assign(cat='all men'),d[d.f>=1].assign(cat='>=1 woman'),d[d.f>=2].assign(cat='2+ women'),d[(d.f>0)&(d.m==0)&(d.u==0)].assign(cat='all women')])
    return out.groupby('cat').rating.agg(n='size',pct=lambda s:round((s<3).mean()*100,1))
for role in ['w','p','d']:
    print(role); print(comp(role,m.movie_id))
