    for var,path in f['tables'].items(): env[var]=pd.read_csv(path)
    out=eval(f['code'],env)
    text=str(out)
    nums=re.findall(r'\d[\d,]*\.?\d*', f['claim'])
    missing=[]
    for n in nums:
        raw=n.replace(',','')
        # check exact substring or rounded variants
        found = n in text
        if not found:
            try:
                v=float(raw)
                for p in range(0,4):
                    if f'{round(v,p):g}' in text or f'{v:.{p}f}' in text:
                        found=True; break
            except: pass
        if not found: missing.append(n)
    print(f['id'], 'missing:', missing)
